INSERT INTO question_catalog(id,subject,topic,basic_range,version,data) VALUES('m101','math1','二次関数',NULL,1,'{"id":"m101","subject":"math1","topic":"二次関数","stem":"関数 $y=x^2-4x+7$ の最小値は？","options":[{"id":"0","text":"−1"},{"id":"1","text":"2"},{"id":"2","text":"3"},{"id":"3","text":"7"}],"correct":"2","explanation":"$x^2-4x+7=(x-2)^2+3$。平方は0以上なので最小値は3。","hints":["平方完成して、平方の項と定数に分けよう。"],"difficulty":1,"expectedSeconds":60,"family":"m101","version":1,"source":"運営作成・初期動作確認問題"}');
INSERT INTO question_catalog(id,subject,topic,basic_range,version,data) VALUES('m102','math1','確率',NULL,1,'{"id":"m102","subject":"math1","topic":"確率","stem":"公平なサイコロを2回投げる。出た目の和が7になる確率は？","options":[{"id":"0","text":"$1/12$"},{"id":"1","text":"$1/6$"},{"id":"2","text":"$1/4$"},{"id":"3","text":"$1/3$"}],"correct":"1","explanation":"全36通り。和が7の組は(1,6),(2,5),(3,4),(4,3),(5,2),(6,1)の6通り。$6/36=1/6$。","hints":["まず、問題文で問われている概念と条件を整理しよう。"],"difficulty":1,"expectedSeconds":60,"family":"m102","version":1,"source":"運営作成・初期動作確認問題"}');
