INSERT INTO question_catalog(id,subject,topic,basic_range,version,data) VALUES('m104','math1','二次関数',NULL,1,'{"id":"m104","subject":"math1","topic":"二次関数","stem":"区間 $-1\\le x\\le3$ で $f(x)=2(x-1)^2-3$ の最大値と最小値の和は？","options":[{"id":"0","text":"−2"},{"id":"1","text":"2"},{"id":"2","text":"5"},{"id":"3","text":"8"}],"correct":"1","explanation":"頂点$x=1$は区間内なので最小値は−3。両端$x=-1,3$で5となり最大値は5。和は2。","hints":["頂点が区間内にあるか確認し、両端の値も比べよう。"],"difficulty":3,"expectedSeconds":120,"family":"m104","version":1,"source":"運営作成・初期動作確認問題"}');
INSERT INTO question_catalog(id,subject,topic,basic_range,version,data) VALUES('m204','math2','数列',NULL,1,'{"id":"m204","subject":"math2","topic":"数列","stem":"和 $1^2+2^2+\\cdots+10^2$ の値は？","options":[{"id":"0","text":"285"},{"id":"1","text":"330"},{"id":"2","text":"385"},{"id":"3","text":"440"}],"correct":"2","explanation":"平方の和は$n(n+1)(2n+1)/6$。$10\\times11\\times21/6=385$。","hints":["平方の和の公式を使うか、各項を計算して確かめよう。"],"difficulty":3,"expectedSeconds":120,"family":"m204","version":1,"source":"運営作成・初期動作確認問題"}');
